1	package com.example.starter.pesticide;
2	
3	import com.example.starter.pesticide.dto.ApiDtos.RecheckRequest;
4	import com.example.starter.pesticide.dto.ApiDtos.RecheckResponse;
5	import com.example.starter.pesticide.dto.ApiDtos.TestRequest;
6	import com.example.starter.pesticide.dto.ApiDtos.TestResponse;
7	import org.springframework.dao.DuplicateKeyException;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	import java.math.BigDecimal;
12	import java.time.Clock;
13	import java.time.Instant;
14	import java.time.LocalDateTime;
15	import java.time.ZoneOffset;
16	
17	/**
18	 * 快检与定量复检服务：抑制率达到 50 判疑似（恰 50 判疑似）；
19	 * 疑似冻结准入，复检合格放行、不合格转监督处置并留样 48 小时；
20	 * 终态后迟到结果只记迟到事件。
21	 */
22	@Service
23	public class TestService {
24	
25	    /** 疑似超标抑制率阈值（单位：%），达到即判疑似 */
26	    public static final BigDecimal SUSPECT_THRESHOLD = new BigDecimal("50");
27	    /** 处置结案留样时长（单位：小时） */
28	    public static final int RETENTION_HOURS = 48;
29	
30	    private final BatchDao batchDao;
31	    private final TestDao testDao;
32	    private final LedgerDao ledgerDao;
33	    private final AlertService alertService;
34	    private final Clock clock;
35	
36	    public TestService(BatchDao batchDao, TestDao testDao, LedgerDao ledgerDao,
37	                       AlertService alertService, Clock clock) {
38	        this.batchDao = batchDao;
39	        this.testDao = testDao;
40	        this.ledgerDao = ledgerDao;
41	        this.alertService = alertService;
42	        this.clock = clock;
43	    }
44	
45	    /**
46	     * 快检：requestId 幂等；批次+项目去重，重复送检 409；终态批次只记迟到事件。
47	     */
48	    @Transactional
49	    public TestResponse rapidTest(TestRequest request) {
50	        String fingerprint = Fingerprint.of(request.requestId(), String.valueOf(request.batchId()),
51	                request.item(), request.inhibitionRate().toPlainString());
52	        var existing = testDao.findTestByRequestId(request.requestId());
53	        if (existing.isPresent()) {
54	            TestDao.TestRow row = existing.get();
55	            if (!row.fingerprint().equals(fingerprint)) {
56	                throw ApiException.conflict("requestId 已使用且业务字段不一致");
57	            }
58	            BatchDao.BatchRow batch = batchDao.findById(row.batchId()).orElseThrow();
59	            return toTestResponse(row, batch.status(), true, false);
60	        }
61	        BatchDao.BatchRow batch = batchDao.lockById(request.batchId())
62	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + request.batchId()));
63	        BatchStatus status = BatchStatus.valueOf(batch.status());
64	        LocalDateTime now = nowUtc();
65	        if (status.isTerminal()) {
66	            ledgerDao.insertLateEvent(batch.id(), "LATE_TEST",
67	                    "item=" + request.item() + ", inhibitionRate=" + request.inhibitionRate(), now);
68	            return new TestResponse(null, request.requestId(), batch.id(), request.item(),
69	                    request.inhibitionRate(), null, batch.status(),
70	                    now.toInstant(ZoneOffset.UTC), false, true);
71	        }
72	        if (status == BatchStatus.FROZEN) {
73	            throw ApiException.conflict("批次疑似冻结待复检，同一批次同时刻只允许一条检测链");
74	        }
75	        if (!batchDao.sampleExists(batch.id(), request.item())) {
76	            throw ApiException.conflict("批次+项目未抽样，不得送检");
77	        }
78	        if (testDao.testExists(batch.id(), request.item())) {
79	            throw ApiException.conflict("批次+项目已检测，拒绝重复送检");
80	        }
81	        String result = request.inhibitionRate().compareTo(SUSPECT_THRESHOLD) >= 0
82	                ? "SUSPECT" : "NORMAL";
83	        long testId;
84	        try {
85	            testId = testDao.insertTest(request.requestId(), fingerprint, batch.id(), request.item(),
86	                    request.inhibitionRate(), result, now);
87	        } catch (DuplicateKeyException e) {
88	            var raced = testDao.findTestByRequestId(request.requestId());
89	            if (raced.isPresent() && raced.get().fingerprint().equals(fingerprint)) {
90	                BatchDao.BatchRow current = batchDao.findById(batch.id()).orElseThrow();
91	                return toTestResponse(raced.get(), current.status(), true, false);
