112	    private <T> List<Outcome<T>> runConcurrently(SupplierFactory<T> factory) throws Exception {
113	        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
114	        try {
115	            CountDownLatch ready = new CountDownLatch(THREADS);
116	            CountDownLatch start = new CountDownLatch(1);
117	            List<Future<Outcome<T>>> futures = new ArrayList<>();
118	            for (int i = 0; i < THREADS; i++) {
