    public record ReleaseResponse(
            Long batchId,
            String status,
            Long admissionId,
            Instant releasedAt,
            boolean replayed) {
    }

    /** 快检记录视图 */
    public record TestView(
            Long testId,
            String item,
            BigDecimal inhibitionRate,
            String result,
            Instant createdAt) {
    }

    /** 迟到事件视图 */
